def rt(v, c, s="Google"):
    return {"value": v, "count": c, "source": s, "as_of": "2026-07"}


def rec(slug, name_vi, name_en, name_ru, cats, lat, lon, addr,
        rating, review_vi, ps_vi, ps_en, ps_ru, pl_vi, pl_en, pl_ru,
        hi_vi, hi_en, hi_ru, practical, tags, sources, photo=None):
    return {
        "id": REG + "-" + slug,
        "slug": slug,
        "region": REG,
        "country": "vietnam",
        "region_name_vi": RNAME,
        "federal_district": FED,
        "name_vi": name_vi,
        "name_ru": name_ru,
        "name_en": name_en,
        "categories": cats,
        "coordinates": {"lat": lat, "lon": lon},
        "address_vi": addr,
        "rating": rating,
        "review_summary_vi": review_vi,
        "presentation_short_vi": ps_vi,
        "presentation_short_en": ps_en,
        "presentation_short_ru": ps_ru,
        "presentation_long_vi": pl_vi,
        "presentation_long_en": pl_en,
        "presentation_long_ru": pl_ru,
        "highlights_vi": hi_vi,
        "highlights_en": hi_en,
        "highlights_ru": hi_ru,
        "practical": practical,
        "photo": photo,
        "photo_credit": None,
        "official_site": None,
        "sources": sources,
        "tags": tags,
        "status": "enriched",
        "last_updated": TODAY,
    }


