    ["Около 3012 м, среди высочайших вершин Вьетнама",
     "Проходит пограничный столб № 79 между Вьетнамом и Китаем",
     "Рододендроны и карликовый бамбук, словно луг над облаками"],
    {"hours_vi": "Trek nhiều ngày; cần giấy phép biên giới.",
     "ticket_vi": "Chi phí theo tour/porter; bắt buộc đăng ký biên phòng.",
     "duration_vi": "Khoảng 2–3 ngày.",
     "best_time_vi": "Mùa hoa đỗ quyên tháng 3–4; mùa khô tháng 10–4.",
     "tips_vi": "Mang giấy tờ tùy thân; chuẩn bị đồ ấm, giày leo tốt và người dẫn đường."},
    ["mountain", "trekking", "adventure", "nature", "border"],
    [{"title": "Cổng thông tin Lai Châu — 'Ba nhất' về các đỉnh núi Lai Châu", "url": "https://laichau.gov.vn/tin-tuc-su-kien/-ba-nhat-ve-cac-dinh-nui-lai-chau.html"}],
